javascript:
function run() { 

const image = 'data:image/gif;base64,';
const child = document.createElement('img');
child.src = image;
child.id = "rockin";
Object.assign(child.style, {
  position: 'fixed',
  top: '50%',
  left: '50%',
  transform: 'translate(-50%, -50%)',
  padding: '20px',
  zIndex: '1000',
  width: '100%',
  height: '100%'
});
  
document.body.appendChild(child);
  
}

run();

setTimeout(() => {
  const dodelete = document.querySelector('#rockin');
  dodelete.remove();
}, 2000);

